package com.sigtm.backend.service;
import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class InspeccionRecepcionCompraService {private final InspeccionRecepcionCompraRepository inspections;private final RecepcionCompraRepository receipts;private final ProductoRepository products;
 @Transactional public InspeccionRecepcionCompra registrar(Long receiptId,Long productId,InspeccionRecepcionCompra data){RecepcionCompra r=receipts.findById(receiptId).orElseThrow(()->new ResourceNotFoundException("Recepción no encontrada"));Producto p=products.findById(productId).orElseThrow(()->new ResourceNotFoundException("Producto no encontrado"));if(!Set.of("ACEPTADA","OBSERVADA","RECHAZADA").contains(data.getResult()))throw new IllegalArgumentException("Resultado inválido");if(data.getAcceptedQuantity()+data.getRejectedQuantity()<1)throw new IllegalArgumentException("Cantidad inspeccionada inválida");data.setReceipt(r);data.setProduct(p);data.setInspectedAt(LocalDateTime.now());return inspections.save(data);}
 @Transactional(readOnly=true) public List<InspeccionRecepcionCompra> listar(Long receiptId){return inspections.findByReceiptIdOrderByInspectedAtDesc(receiptId);}}
